import{_ as t,c as o,b as a,a0 as n}from"./chunks/framework.DZ_FiXNr.js";const r="/images/command_center.webp",m=JSON.parse(`{"title":"Command Center","description":"Start here to see what needs attention and choose your next action. Command Center brings together your setup, LUCIA's current recommendation, recurring checks, and changes in your podcast's visibility.","frontmatter":{},"headers":[],"relativePath":"features/command-center.md","filePath":"features/command-center.md"}`),s={name:"features/command-center.md"};function i(h,e,c,d,l,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="command-center" tabindex="-1">Command Center <a class="header-anchor" href="#command-center" aria-label="Permalink to &quot;Command Center&quot;">​</a></h1><p>Start here to see what needs attention and choose your next action. Command Center brings together your setup, LUCIA&#39;s current recommendation, recurring checks, and changes in your podcast&#39;s visibility.</p><p><strong>To access:</strong> click <strong>Command Center</strong> in the sidebar. The tabs are <strong>Home · Positioning Strategy · Show optimization · Planner · Pulse</strong>, in that order. This guide covers <strong>Home</strong>.</p><p><a href="/images/command_center.webp" title="Open screenshot at full size"><img src="'+r+'" alt="Command Center with LUCIA&#39;s priority, setup status, and next actions"></a></p><h2 id="start-with-lucia-s-priority" tabindex="-1">Start with LUCIA&#39;s priority <a class="header-anchor" href="#start-with-lucia-s-priority" aria-label="Permalink to &quot;Start with LUCIA&#39;s priority&quot;">​</a></h2><p>When a recommendation is available, <strong>LUCIA&#39;s priority this week</strong> highlights a concrete action for your podcast. Choose <strong>Do it with LUCIA</strong> when available to work through the recommended action in <a href="/features/lucia-ai-assistant.html">Podcast coach</a>. Other notes offer <strong>Open in LUCIA</strong> to review the context and next step.</p><p>Setup tasks and recurring checks remain available below. The priority helps you decide where to begin without treating every task as equally urgent.</p><h2 id="understand-your-optimization-setup" tabindex="-1">Understand your optimization setup <a class="header-anchor" href="#understand-your-optimization-setup" aria-label="Permalink to &quot;Understand your optimization setup&quot;">​</a></h2><p>The <strong>Your show is X% optimized</strong> card measures setup and optimization inputs. Below it, three tiles show:</p><ul><li><strong>Positioning</strong> — how many slots are filled across your six positioning sections. Open <a href="/features/positioning.html">Positioning Strategy</a> to add or review topics.</li><li><strong>Keyword strategy</strong> — your show keywords, which guide show-level titles and descriptions. Open <a href="/features/keyword-strategy.html">Strategy</a> to review them.</li><li><strong>Distribution</strong> — coverage across the main listening platforms. Open <a href="/features/distribution-health.html">Distribution</a> to check listings and feed health.</li></ul><p>Positioning completion and review freshness are different. <strong>Mark as still accurate</strong> confirms that you reviewed existing topics; it doesn&#39;t fill empty slots or raise completion by itself.</p><p>Optimization is an input measure. Your separate <strong>Visibility outcome</strong> describes how your show is performing in discovery.</p><h2 id="complete-foundation" tabindex="-1">Complete Foundation <a class="header-anchor" href="#complete-foundation" aria-label="Permalink to &quot;Complete Foundation&quot;">​</a></h2><p>Expand <strong>Foundation</strong> to review the setup checklist and any credits you&#39;ve earned. Follow the steps shown for your podcast: they cover choosing or reviewing show keywords and competitors, checking platforms, and planning an episode. Your progress is shown as completed steps, with the next useful action linked directly.</p><p>Completed setup steps can earn credits for <a href="/features/social-publishing.html">Social Publishing</a>. The checklist shows which steps and rewards apply; completing setup does not publish anything.</p><h2 id="other-tasks-and-checks" tabindex="-1">Other tasks and checks <a class="header-anchor" href="#other-tasks-and-checks" aria-label="Permalink to &quot;Other tasks and checks&quot;">​</a></h2><p>Use this list for recurring keyword reviews, competitor checks, description improvements, and relevant YouTube actions. Open a task to reach the page where you can act. Tasks can change as your data and setup change.</p><p>If a YouTube title suggestion appears, it opens the relevant episode in <a href="/features/youtube-insights.html">Analytics → YouTube</a>. Apply the title yourself in YouTube Studio.</p><h2 id="get-your-show-seen" tabindex="-1">Get your show seen <a class="header-anchor" href="#get-your-show-seen" aria-label="Permalink to &quot;Get your show seen&quot;">​</a></h2><p><strong>Visibility outcome</strong> shows your relative position and recent movement. <strong>Open visibility progress</strong> leads to the <a href="/features/visibility-progress.html">score breakdown and timeline</a>.</p><p>The <strong>Social</strong> card offers a next action based on your progress: connect a channel, create clips, or publish a finished clip. Reconnect warnings need attention before you rely on scheduled posts.</p><h2 id="what-s-changing" tabindex="-1">What&#39;s changing <a class="header-anchor" href="#what-s-changing" aria-label="Permalink to &quot;What&#39;s changing&quot;">​</a></h2><p>Review notable keyword movements and competitor opportunities here. After time away, the page can emphasize what changed since your last visit. Each insight links to the relevant evidence; a ranking movement alone does not prove what caused it.</p><h2 id="move-from-setup-to-production" tabindex="-1">Move from setup to production <a class="header-anchor" href="#move-from-setup-to-production" aria-label="Permalink to &quot;Move from setup to production&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tab</th><th>Use it for</th></tr></thead><tbody><tr><td><a href="/features/positioning.html">Positioning Strategy</a></td><td>Define and review who your show serves and what makes it different</td></tr><tr><td><a href="/features/show-optimization.html">Show optimization</a></td><td>Improve show title, author, description, and cover</td></tr><tr><td><a href="/features/planner.html">Planner</a></td><td>Plan and optimize individual episodes</td></tr><tr><td><a href="/features/pulse.html">Pulse</a></td><td>Explore timely topics and supporting sources</td></tr></tbody></table><p>For an unpublished podcast, Home is called <strong>Design</strong>. See <a href="/getting-started/pre-launch-planning.html">Pre-launch Planning</a> for its rollout and launch-readiness flow. Agency teams can review multiple shows in the <a href="/features/agency-workspace.html">Agency workspace</a>.</p>',26)])])}const g=t(s,[["render",i]]);export{m as __pageData,g as default};
